      return -1;
   const uint8_t *payload = input + AIMEE_DB2_ENVELOPE_HEADER_LEN;
   uint32_t decoded_limit = aimee_db2_get_u32(payload);
   uint32_t decoded_scope = aimee_db2_get_u32(payload + 4u);
