      memory_content[0] = '\0';
   if (!memory_key || memory_key_capacity < (size_t)AIMEE_DB2_MEMORY_CONFLICTING_L2_MEMORY_KEY_MAX + 1u || !memory_content || memory_content_capacity < (size_t)AIMEE_DB2_MEMORY_CONFLICTING_L2_MEMORY_CONTENT_MAX + 1u)
      return -1;
