         return -1;
      rows[index].use_count = aimee_db2_get_u32(payload + cursor);
      cursor += 4u;
      if (rows[index].use_count > AIMEE_DB2_MEMORY_DEDUPE_CANDIDATES_USE_COUNT_MAX)
         return -1;
      if (cursor + 4u > payload_len)
         return -1;
