      return -1;
   size_t first_len = 0u, second_len = 0u;
   while (first_len <= AIMEE_DB2_ENTITY_PROFILE_FRESH_FIRST_MAX && entity_id[first_len])
      ++first_len;
   while (second_len <= AIMEE_DB2_ENTITY_PROFILE_FRESH_SECOND_MAX && window[second_len])
      ++second_len;
