static inline int aimee_db2_bandit_decision_close_request_encode(const char *bandit_decision_id, double reward,
                                                   uint8_t *output, size_t capacity,
                                                   uint32_t *output_len)
{
   if (output_len)
      *output_len = 0u;
   if (!bandit_decision_id || !output || !output_len)
      return -1;
   size_t bandit_decision_id_len = 0u;
   while (bandit_decision_id_len <= AIMEE_DB2_BANDIT_DECISION_CLOSE_BANDIT_DECISION_ID_MAX && bandit_decision_id[bandit_decision_id_len])
      ++bandit_decision_id_len;
   if (bandit_decision_id_len < AIMEE_DB2_BANDIT_DECISION_CLOSE_BANDIT_DECISION_ID_MIN || bandit_decision_id_len > AIMEE_DB2_BANDIT_DECISION_CLOSE_BANDIT_DECISION_ID_MAX ||
       (aimee_db2_binary64_bits(reward) & 0x7fffffffffffffffull) > AIMEE_DB2_BANDIT_DECISION_CLOSE_REWARD_MAX_MAGNITUDE_BITS)
      return -1;
   uint8_t scratch[AIMEE_DB2_BANDIT_DECISION_CLOSE_REQUEST_MAX_LEN];
   uint8_t *payload = scratch;
   uint32_t cursor = 0u;
   aimee_db2_put_u32(payload + cursor, (uint32_t)bandit_decision_id_len);
   memcpy(payload + cursor + 4u, bandit_decision_id, bandit_decision_id_len);
   cursor += 4u + (uint32_t)bandit_decision_id_len;
   aimee_db2_put_u64(payload + cursor, aimee_db2_binary64_bits(reward));
   cursor += 8u;
   if (capacity < (size_t)AIMEE_DB2_ENVELOPE_HEADER_LEN + cursor ||
       aimee_db2_request_header_encode(AIMEE_DB2_OPERATION_BANDIT_DECISION_CLOSE, 0u, cursor, output,
                                       capacity) != 0)
      return -1;
   memcpy(output + AIMEE_DB2_ENVELOPE_HEADER_LEN, scratch, cursor);
   *output_len = AIMEE_DB2_ENVELOPE_HEADER_LEN + cursor;
   return 0;
}

static inline int aimee_db2_bandit_decision_close_request_decode(const uint8_t *input, size_t input_len,
                                                   char *bandit_decision_id, size_t bandit_decision_id_capacity, double *reward)
{
   if (bandit_decision_id && bandit_decision_id_capacity)
      bandit_decision_id[0] = '\0';
   if (reward)
      *reward = 0.0;
   if (!bandit_decision_id || bandit_decision_id_capacity < (size_t)AIMEE_DB2_BANDIT_DECISION_CLOSE_BANDIT_DECISION_ID_MAX + 1u || !reward)
      return -1;
   aimee_db2_request_header_t header = {0};
   if (aimee_db2_request_header_decode(input, input_len, &header) != 0 ||
       header.operation != AIMEE_DB2_OPERATION_BANDIT_DECISION_CLOSE || header.flags != 0u ||
       input_len < AIMEE_DB2_BANDIT_DECISION_CLOSE_REQUEST_MIN_LEN ||
       input_len > AIMEE_DB2_BANDIT_DECISION_CLOSE_REQUEST_MAX_LEN)
      return -1;
   const uint8_t *payload = input + AIMEE_DB2_ENVELOPE_HEADER_LEN;
   uint32_t payload_len = header.payload_len;
   uint32_t cursor = 0u;
   if (aimee_db2_memory_row_take(payload, payload_len, &cursor, bandit_decision_id,
                                 AIMEE_DB2_BANDIT_DECISION_CLOSE_BANDIT_DECISION_ID_MAX) != 0)
      return -1;
   {
      size_t taken = 0u;
      while (bandit_decision_id[taken])
         ++taken;
      if (taken < AIMEE_DB2_BANDIT_DECISION_CLOSE_BANDIT_DECISION_ID_MIN)
         return -1;
   }
   if (cursor + 8u > payload_len)
      return -1;
   {
      uint64_t bits = aimee_db2_get_u64(payload + cursor);
      cursor += 8u;
      if ((bits & 0x7fffffffffffffffull) > AIMEE_DB2_BANDIT_DECISION_CLOSE_REWARD_MAX_MAGNITUDE_BITS)
         return -1;
      *reward = aimee_db2_binary64_value(bits);
   }
   if (cursor != payload_len)
      return -1;
   return 0;
}

