   while (decision_subject_filter_len <= AIMEE_DB2_DECISION_LOG_LIST_SCOPED_DECISION_SUBJECT_FILTER_MAX && decision_subject_filter[decision_subject_filter_len])
      ++decision_subject_filter_len;
