         cursor += 8u;
         if ((bits & 0x7fffffffffffffffull) > AIMEE_DB2_KB_DOC_ASSETS_LIST_Y0_MAX_MAGNITUDE_BITS)
            return -1;
         rows[index].y0 = aimee_db2_binary64_value(bits);
