   if (!scope_type || !output || !output_len)
      return -1;
   size_t scope_len = 0u;
   while (scope_len <= AIMEE_DB2_HAS_SCOPE_TYPE_SCOPE_MAX && scope_type[scope_len])
      ++scope_len;
   size_t payload_len = 12u + scope_len;
